(async () => {
  const bytes = Uint8Array.from(atob(""), c => c.charCodeAt(0));
  const script = document.createElement('script');
  script.textContent = await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).text();
  document.head.append(script);
  script.remove();
})().catch(error => { window.dispatchEvent(new ErrorEvent("error", { error, message: String(error) })); throw error; });
